import json, re
from pathlib import Path

def extract_user_queries(fp, limit=40):
    print("\n========", Path(fp).name[:8], "========")
    n = 0
    with open(fp) as f:
        for line in f:
            try:
                o = json.loads(line)
            except Exception:
                continue
            msg = o.get("message") if isinstance(o.get("message"), dict) else o
            role = (msg or {}).get("role") or o.get("role") or ""
            c = (msg or {}).get("content")
            text = ""
            if isinstance(c, str):
                text = c
            elif isinstance(c, list):
                parts = []
                for p in c:
                    if isinstance(p, dict) and p.get("type") in ("text", "input_text"):
                        parts.append(p.get("text") or "")
                text = "\n".join(parts)
            if role not in ("user", "human"):
                continue
            m = re.search(r"<user_query>\s*(.*?)\s*</user_query>", text, re.S)
            if m:
                t = m.group(1).strip()
            else:
                # skip bootstrap dumps
                if "记忆冷启动" in text or "记忆蒸馏器" in text or text.startswith("<"):
                    continue
                t = text.strip()
            t = re.sub(r"\s+", " ", t)
            if len(t) > 280:
                t = t[:280] + "…"
            if not t:
                continue
            print(f"- {t}")
            n += 1
            if n >= limit:
                break
    print(f"count_shown={n}")

